-- 乾霖 · Amazon Payments 回款导入（2026-10-01 ~ 2026-11-23，53 笔）
-- 来源：Amazon 后台收款流水截图（KK 2026-11-23 提供）
-- 口径：received_amount = 银行实际到账；amount_cny = 原币 × 7.6（EUR）/ 9.2（GBP）
-- 说明：这是「到账」数据，不是结算单；sales/commission/VAT 三列留空，待结算报告补

delete from public.recoveries where store = '乾霖';


-- 校验
select currency, count(*) as 笔数, round(sum(received_amount),2) as 原币合计, round(sum(amount_cny),2) as 折人民币
from public.recoveries where store='乾霖' group by currency;
-- 期望：EUR 52 笔 / 26,260.45 / 199,579.42 ； GBP 1 笔 / 2.04 / 18.77 ；合计 ¥199,598.19
